mapper.update:
UPDATE TB_TODO_SHARE
SET PERMISSION = #{permission}
WHERE SHARE_ID = #{shareId}

mapper.delete:
DELETE FROM TB_TODO_SHARE
WHERE TODO_ID = #{todoId}
  AND SHARED_USER_ID = #{sharedUserId}

mapper.select:
SELECT COUNT(*) > 0
FROM TB_TODO_SHARE
WHERE TODO_ID = #{todoId}
  AND SHARED_USER_ID = #{sharedUserId}

SELECT PERMISSION
FROM TB_TODO_SHARE
WHERE TODO_ID = #{todoId}
  AND SHARED_USER_ID = #{sharedUserId}

SELECT COUNT(*)
FROM TB_TODO_SHARE
WHERE TODO_ID = #{todoId}
